+        """The destination can be a numpy array as well as a torch tensor."""
+        path = os.path.join(self.tempdir.name, "numpy.safetensors")
+        tensors = {
+            "a": np.arange(12, dtype=np.float32).reshape(3, 4),
+            "b": np.arange(8, dtype=np.int64),
